#include <stdio.h>
#include <string.h>
/*
 * ex05：Horn 子句前向链（Datalog 的最小实现）
 * 为什么：Prolog / Soufflé / 规则引擎 / K8s 准入策略，本质都在跑这件事：
 *        「已知事实 + 形如 body => head 的规则」反复推，直到不再长出新事实。
 * 本例用祖先关系演示：两轮就能从 4 条 parent 事实推出全部祖先对。
 */
static const char *names[] = {"tom", "bob", "ann", "pat", "jim"};
#define N 5
static int parent[N][N];
static int anc[N][N];

static int id_of(const char *s) {
    for (int i = 0; i < N; i++) if (strcmp(names[i], s) == 0) return i;
    return -1;
}
static void add_fact(const char *a, const char *b) { parent[id_of(a)][id_of(b)] = 1; }

int main(void) {
    add_fact("tom", "bob");
    add_fact("bob", "ann");
    add_fact("bob", "pat");
    add_fact("pat", "jim");

    printf("facts (parent):\n");
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (parent[i][j]) printf("  parent(%s, %s)\n", names[i], names[j]);

    /* rule 1: parent(x,y) => ancestor(x,y) */
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (parent[i][j]) anc[i][j] = 1;

    int round = 0, total = 0;
    for (;;) {
        int added = 0;
        round++;
        /* rule 2: parent(x,y) & ancestor(y,z) => ancestor(x,z) */
        for (int x = 0; x < N; x++)
            for (int y = 0; y < N; y++) {
                if (!parent[x][y]) continue;
                for (int z = 0; z < N; z++) {
                    if (anc[y][z] && !anc[x][z]) {
                        anc[x][z] = 1;
                        added++;
                        printf("round %d: + ancestor(%s, %s)   [parent(%s,%s) & ancestor(%s,%s)]\n",
                               round, names[x], names[z], names[x], names[y], names[y], names[z]);
                    }
                }
            }
        total += added;
        if (!added) break;
    }
    printf("\nrounds to fixpoint: %d, new facts derived: %d\n", round - 1, total);
    printf("all ancestors:\n");
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (anc[i][j]) printf("  ancestor(%s, %s)\n", names[i], names[j]);
    printf("\nnote: the recursion terminates because the relation is finite --\n");
    printf("      forward chaining is exactly 'least fixpoint of a monotone operator'.\n");
    return 0;
}
